CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('CUSTOMER','ADMIN')), enabled BOOLEAN NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE user_profiles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id), full_name VARCHAR(120), phone VARCHAR(30), delivery_address TEXT);
